333	// externalDenylist reads the optional deny list. It is never in the repository:
334	// its terms are the names of an instance that must not appear anywhere in it.
335	func externalDenylist(t *testing.T) []string {
336		t.Helper()
337		path := os.Getenv(denylistEnv)
338		if path == "" {
339			t.Logf("%s is not set: the external deny list was not used", denylistEnv)
340			return nil
341		}
342		data, err := os.ReadFile(path)
343		if err != nil {
344			t.Fatalf("%s names a file that cannot be read: %v", denylistEnv, err)
345		}
346		var terms []string
347		for line := range bytes.Lines(data) {
348			term := strings.TrimSpace(string(line))
349			if term != "" && !strings.HasPrefix(term, "#") {
350				terms = append(terms, term)
351			}
352		}
353		return terms
354	}
